const NEUTRAL_BASE_SPEC = Object.freeze({warrior:'arms',paladin:'ret',druid:'balance',priest:'shadow',mage:'fire',hunter:'mm',rogue:'combat',warlock:'aff'});
function isNeutralTraining(p) {
  if (!p || p.neutralTraining !== true) return false;
  if (!Number.isInteger(p.level) || p.level < 1 || p.level > XPC.cap) throw new RangeError('Neutral training requires an explicit own level');
  if (p.level >= 15) return false;
  if (p.proto || p.integratedArms) throw new Error('Neutral training cannot use a specialization prototype');
  return true;
}
function applyNeutralTraining(h, p, aura) {
  if (!isNeutralTraining(p)) return;
  const key = NEUTRAL_BASE_SPEC[p.cls], base = CLASSES[p.cls].specs[key];
  const hs = heroStats(p.cls,key,h.level,p.statBonuses), rb = p.rb || 0;
  Object.assign(h, {neutralTraining:true,spec:null,ai:'neutral_training',specName:'Учебный набор',role:'training',
    maxHp:Math.round(hs.hp*(1+(aura.hp||0))*(1+rb)),atk:hs.rawAtk*(1+rb),armor:hs.armor,res:base.res,
    spd:base.spd*(1+(aura.spd||0)),crit:base.crit+(aura.crit||0),threatMult:1,type:base.type,healPow:0,
    fury:false,shadowform:false,pids:[],skills:api.neutralTraining.active(p.cls,h.level),primary:hs.primary,
    primaryMultiplier:1+rb,resource:hs.resource,maxEnergy:hs.resource==='energy'?ENERGY_CFG.max:0,
    energy:hs.resource==='energy'?ENERGY_CFG.start:0,maxRage:hs.resource==='rage'?RAGE_CFG.max:0,
    rage:RAGE_CFG.start,maxMana:Math.round(hs.mana*(1+rb)),mana:Math.round(hs.mana*(1+rb)),maxCp:p.cls==='rogue'?5:0,cp:0});
  h.hp=h.maxHp;
}
function neutralTrainingAct(st,h) {
