      if(control&&cast('entangle',()=>{effect(control,'entangle','dot',{mult:0.7,turns:3});effect(control,'entangle','stun',{turns:2});}))return;
      if(!hasDot('Лунный огонь')&&cast('moonfire',()=>{damage(st,h,t,0.35,{type:'magic'});if(t.hp>0)dot(st,h,t,'moonfire',0.4);}))return;
      hit('wrath',1,'magic');return;
