      cast('fireball',()=>{damage(st,h,t,1.3,{type:'magic'});if(t.hp>0)addEffect(t,{kind:'dot',mult:0.3,turns:3,src:h.id,name:'Горение',icon:SKILLS.fireball.icon});});return;
    case 'hunter':
      if(!hasDot('Укус змеи')&&cast('serpent',()=>{damage(st,h,t,0.4);if(t.hp>0)effect(t,'serpent','dot',{mult:0.3,turns:5});}))return;
