      if(!hasDot('Жертвенный огонь')&&cast('immolate',()=>{damage(st,h,t,0.7,{type:'magic'});if(t.hp>0)effect(t,'immolate','dot',{mult:0.25,turns:5});}))return;
      if(!hasDot('Порча')&&cast('corruption',()=>effect(t,'corruption','dot',{mult:0.3,turns:5})))return;
      hit('shadowbolt',1.3,'magic');return;
  }
}

